// A fake DaemonClient whose item/reconnect listeners the test can fire.
function makeClient(): {
  client: DaemonClient;
  emitItem: (item: ChatItem) => void;
  fireDisconnect: () => void;
  fireReconnect: () => void;
  fireVerdictAck: (ack: VerdictAck) => void;
  fireGroupsChanged: () => void;
  emitLiveText: (event: LiveTextEvent) => void;
  emitRunStatus: (event: RunStatusEvent) => void;
  emitRunDeleted: (runId: string) => void;
  emitRunsChanged: (runs: ChatRun[]) => void;
  fireProjectsChanged: (textsOnly?: boolean) => void;
  fireLessonsChanged: (runId: string | null) => void;
  joinRun: ReturnType<typeof vi.fn>;
} {
  const projectsChangedListeners = new Set<
    (event: { projectId: string; textsOnly: boolean }) => void
  >();
  /**
   * A SET for `runStatusListeners`' reason below: the open run's state hook
   * (`use-run-state.ts`) listens for structural rows beside `use-chat-run`.
   */
  const itemListeners = new Set<(item: ChatItem) => void>();
  const reconnectListeners = new Set<(error?: Error) => void>();
  const disconnectListeners = new Set<() => void>();
  const verdictAckListeners = new Set<(ack: VerdictAck) => void>();
  const lessonsChangedListeners = new Set<
    (event: { runId: string | null }) => void
  >();
  const groupsChangedListeners = new Set<() => void>();
  const liveTextListeners = new Set<(event: LiveTextEvent) => void>();
  /**
   * Every listener is a SET: the real client fans each event out to every
   * subscriber, and this screen has more than one — `use-chat-run` for the
   * badge, `use-chat-totals` for the fetched spend, and a whole second chat
   * screen inside an analysis popup. Holding a single listener let whichever
   * subscribed last silence the other, which is a defect of the double and
   * never of the client.
   */
  const runStatusListeners = new Set<(event: RunStatusEvent) => void>();
  const runDeletedListeners = new Set<(runId: string) => void>();
  const runsChangedListeners = new Set<(runs: ChatRun[]) => void>();
  const joinRun = vi.fn(async () => {});
  const client = {
    onItem: (l: (item: ChatItem) => void) => {
      itemListeners.add(l);
      return () => {
        itemListeners.delete(l);
      };
    },
    onReconnect: (l: (error?: Error) => void) => {
      reconnectListeners.add(l);
      return () => {
        reconnectListeners.delete(l);
      };
    },
    onDisconnect: (l: () => void) => {
      disconnectListeners.add(l);
      return () => {
        disconnectListeners.delete(l);
      };
    },
    onLiveText: (l: (event: LiveTextEvent) => void) => {
      liveTextListeners.add(l);
      return () => {
        liveTextListeners.delete(l);
      };
    },
    onRunStatus: (l: (event: RunStatusEvent) => void) => {
      runStatusListeners.add(l);
      return () => {
        runStatusListeners.delete(l);
      };
    },
    onRunDeleted: (l: (runId: string) => void) => {
      runDeletedListeners.add(l);
      return () => {
        runDeletedListeners.delete(l);
      };
    },
    onRunsChanged: (l: (runs: ChatRun[]) => void) => {
      runsChangedListeners.add(l);
      return () => {
        runsChangedListeners.delete(l);
      };
    },
    onGroupsChanged: (l: () => void) => {
      groupsChangedListeners.add(l);
      return () => {
        groupsChangedListeners.delete(l);
      };
    },
    onSharesChanged: () => () => undefined,
    onThreadMessagesChanged: () => () => undefined,
    onProjectsChanged: (
      l: (event: { projectId: string; textsOnly: boolean }) => void,
    ) => {
      projectsChangedListeners.add(l);
      return () => {
        projectsChangedListeners.delete(l);
      };
    },
    onVerdictAck: (l: (ack: VerdictAck) => void) => {
      verdictAckListeners.add(l);
      return () => {
        verdictAckListeners.delete(l);
      };
    },
    onLessonsChanged: (l: (event: { runId: string | null }) => void) => {
      lessonsChangedListeners.add(l);
      return () => {
        lessonsChangedListeners.delete(l);
      };
    },
    joinRun,
    leaveRun: vi.fn(),
    sendVerdict: vi.fn(),
  } as unknown as DaemonClient;
  return {
    client,
    fireLessonsChanged: (runId) => {
      for (const listener of [...lessonsChangedListeners]) {
        listener({ runId });
      }
    },
    fireProjectsChanged: (textsOnly = false) => {
      for (const listener of [...projectsChangedListeners]) {
        listener({ projectId: 'p-any', textsOnly });
      }
    },
    emitItem: (item) => {
      for (const listener of [...itemListeners]) {
        listener(item);
      }
    },
    fireDisconnect: () => {
      for (const listener of [...disconnectListeners]) {
        listener();
      }
    },
    fireReconnect: () => {
      for (const listener of [...reconnectListeners]) {
        listener();
      }
    },
    fireVerdictAck: (ack) => {
      for (const listener of [...verdictAckListeners]) {
        listener(ack);
      }
    },
    fireGroupsChanged: () => {
      for (const listener of [...groupsChangedListeners]) {
        listener();
      }
    },
    emitLiveText: (event) => {
      for (const listener of [...liveTextListeners]) {
        listener(event);
      }
    },
    emitRunStatus: (event) => {
      for (const listener of [...runStatusListeners]) {
        listener(event);
      }
    },
    emitRunDeleted: (runId: string) => {
      for (const listener of [...runDeletedListeners]) {
        listener(runId);
      }
    },
    emitRunsChanged: (runs: ChatRun[]) => {
      for (const listener of [...runsChangedListeners]) {
        listener(runs);
      }
    },
    joinRun,
  };
}

