const roots: Root[] = [];

async function mount(
  client: DaemonClient,
  onOpenSettings?: (section: SettingsSection) => void,
  props: Partial<Parameters<typeof Chats>[0]> = {},
): Promise<HTMLElement> {
  const container = document.createElement('div');
  document.body.appendChild(container);
  const root = createRoot(container);
  roots.push(root);
  await act(async () => {
    root.render(
      <Chats
        client={client}
        handle={handle}
        onOpenSettings={onOpenSettings}
        {...props}
      />,
    );
  });
  return container;
}

async function clickRun(container: HTMLElement, title: string): Promise<void> {
  // `li[draggable]` is the ROW. Every section — a group, or the loose list — is
  // itself an `li` wrapping its rows, so a plain `li` search finds the SECTION
  // first and clicks whichever row happens to be at the top of it.
  const li = [
    ...container.querySelectorAll<HTMLElement>('li[draggable="true"]'),
  ].find((el) => el.textContent?.includes(title));
  // The row's activation surface is its overlay button (the li's first child).
  const activate = li?.querySelector<HTMLButtonElement>('button');
  await act(async () => {
    activate?.click();
  });
  await expandAgentsPanel(container);
}

/**
 * Unfold the agents panel, which starts folded in a thread nobody opened it
 * in — nearly every case reaching the panel is about what it draws open.
 */
async function expandAgentsPanel(container: HTMLElement): Promise<void> {
  const expand = container.querySelector<HTMLButtonElement>(
    'button[aria-label="Expand agents panel"]',
  );
  await act(async () => {
    expand?.click();
  });
}

/**
 * Open the thread's notes popup from the agents panel's control row and hand
 * back its field — the notes live in a popup, not in the column.
 */
async function openThreadNotes(
  container: HTMLElement,
): Promise<HTMLTextAreaElement> {
  const button = container.querySelector<HTMLButtonElement>(
    'button[aria-label="Open thread notes"], button[aria-label="Add thread notes"]',
  );
  await act(async () => {
    button?.click();
  });
  return container.querySelector<HTMLTextAreaElement>(
    '[role="dialog"] textarea[aria-label="Thread notes"]',
  )!;
}

/** The composer's round icon actions, looked up by their accessible name. */
/** An element's class list as exact tokens (substring checks lie about `shrink-0`). */
function classesOf(el: Element): string[] {
  return (el.getAttribute('class') ?? '').split(/\s+/).filter(Boolean);
}

function composerButton(
  container: HTMLElement,
  label: 'Send' | 'Stop',
): HTMLButtonElement | null {
  return container.querySelector<HTMLButtonElement>(
    `button[aria-label="${label}"]`,
  );
}

/** The composer's target picker. The menu is OURS, so its rows are real DOM. */
/**
 * The composer's model chip (new-run and open-chat alike) — ONE control now,
 * carrying the model AND every setting that model can be run with.
 *
 * There is no longer a chip per axis: they are labelled BLOCKS inside this
 * one panel (`ModelSettingsSelect`), so a test that used to look for a second
 * trigger now asks {@link menuBlock} what the open panel offers.
 */
function modelTrigger(container: HTMLElement): HTMLButtonElement {
  return [
    ...container.querySelectorAll<HTMLButtonElement>('[data-menu-trigger]'),
  ].find(
    (trigger) =>
      trigger.getAttribute('aria-label') === 'Model and its settings',
  )!;
}

function targetTrigger(container: HTMLElement): HTMLButtonElement {
  return container.querySelector<HTMLButtonElement>(
    '[data-menu-trigger][aria-label="Agent or team for new runs"]',
  )!;
}

/**
 * Open a composer menu and click the row with this exact label.
 *
 * Matched on the row's LABEL span, not on its whole `textContent`: a `MenuItem`
 * may carry a right-aligned `hint` (the model picker states each model's effort
 * there), and comparing the concatenation would need every caller to spell the
 * hint too — so a hint added to a picker would break every unrelated pick.
 */
async function pickMenuRow(
  container: HTMLElement,
  trigger: HTMLButtonElement,
  rowText: string,
): Promise<void> {
  await act(async () => {
    trigger.dispatchEvent(new MouseEvent('click', { bubbles: true }));
  });
  // By SLOT, not by span position: a row wraps its label in a column so a
  // sub-label can sit under it, and the first span is then that wrapper —
  // whose text is the two lines joined.
  const row = [
    ...container.querySelectorAll<HTMLElement>('[role="option"]'),
  ].find(
    (o) =>
      o.querySelector('[data-slot="menu-item-label"]')?.textContent === rowText,
  );
  if (!row) {
    throw new Error(`no menu row labelled "${rowText}"`);
  }
  await act(async () => {
    row.dispatchEvent(new MouseEvent('click', { bubbles: true }));
  });
}

/** Read a menu's rows without committing to one (open, read, close). */
async function menuRows(
  container: HTMLElement,
  trigger: HTMLButtonElement,
): Promise<string[]> {
  const toggle = async (): Promise<void> => {
    await act(async () => {
      trigger.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    });
  };
  await toggle();
  const rows = [...container.querySelectorAll('[role="option"]')].map(
    (o) => o.textContent ?? '',
  );
  await toggle();
  return rows;
}

/**
 * The rows of ONE axis of the model panel, read without committing.
 *
 * The panel is TWO levels: a first-level row per axis (its name and where it
 * stands), and that axis's values behind it. Undefined when the panel carries
 * no such row, which is how "this model offers no effort axis" now reads —
 * where it once was a missing chip, then a missing block.
 */
async function settingRows(
  container: HTMLElement,
  axis: string,
): Promise<string[] | undefined> {
  await act(async () => {
    modelTrigger(container).dispatchEvent(
      new MouseEvent('click', { bubbles: true }),
    );
  });
  const row = axisRow(container, axis);
  if (!row) {
    await act(async () => {
      modelTrigger(container).dispatchEvent(
        new MouseEvent('click', { bubbles: true }),
      );
    });
    return undefined;
  }
  await act(async () => {
    row.dispatchEvent(new MouseEvent('click', { bubbles: true }));
  });
  const rows = submenuRows(container).map(
    (o) => o.querySelector('span')?.textContent ?? '',
  );
  await act(async () => {
    modelTrigger(container).dispatchEvent(
      new MouseEvent('click', { bubbles: true }),
    );
  });
  return rows;
}

/** A first-level row of the open model panel, by its axis name. */
function axisRow(
  container: HTMLElement,
  axis: string,
): HTMLElement | undefined {
  const panel = container.querySelector<HTMLElement>('[role="listbox"]');
  return panel
    ? [...panel.querySelectorAll<HTMLElement>('[role="option"]')].find(
        (o) => o.querySelector('span')?.textContent === axis,
      )
    : undefined;
}

/** The rows of the SECOND panel — the one an axis row opened. */
function submenuRows(container: HTMLElement): HTMLElement[] {
  const panels = [
    ...container.querySelectorAll<HTMLElement>('[role="listbox"]'),
  ];
  const child = panels[1];
  return child
    ? [...child.querySelectorAll<HTMLElement>('[role="option"]')]
    : [];
}

/** Pick one value of one axis: open the panel, open the axis, take the row. */
async function pickSetting(
  container: HTMLElement,
  axis: string,
  rowText: string,
): Promise<void> {
  await act(async () => {
    modelTrigger(container).dispatchEvent(
      new MouseEvent('click', { bubbles: true }),
    );
  });
  const row = axisRow(container, axis);
  if (!row) {
    throw new Error(`no "${axis}" row in the model panel`);
  }
  await act(async () => {
    row.dispatchEvent(new MouseEvent('click', { bubbles: true }));
  });
  const target = submenuRows(container).find(
    (o) => o.querySelector('span')?.textContent === rowText,
  );
  if (!target) {
    throw new Error(`no "${rowText}" row under "${axis}"`);
  }
  await act(async () => {
    target.dispatchEvent(new MouseEvent('click', { bubbles: true }));
  });
}

