    contextEstimated: false,
    contextWindowTokens: null,
    configDir: null,
    configDirPin: null,
    groupId: null,
    taskId: null,
    pinnedPosition: null,
    color: null,
    createdAt: 'later',
    updatedAt: 'later',
    archivedAt: null,
    attentionAt: null,
    seenAt: null,
    notes: null,
    lastMessage: null,
    lastActivityAt: null,
    pullRequests: [],
    workedMs: null,
