  it('forgets the remembered context window when the model chip changes model', async () => {
    // A window size belongs to the MODEL that offered it, so one remembered
    // from the previous model is one the new model may refuse — the chip then
    // reads "default window" while the run is created carrying the old size,
    // and every turn declines it. The daemon already drops it on a patch that
    // changes model; the NEW-run path has to do the same here.
    stubSettings({
      lastModels: { claude: 'sonnet' },
      lastContextWindows: { claude: '1m' },
    });
    const { client } = makeClient();
    const container = await mount(client);

    await pickSetting(container, 'Model', 'opus');

    // The map WITHOUT claude's entry — not merely "some write happened": the
    // stored word is what reaches the next run, so an unchanged `{claude:'1m'}`
    // is exactly the defect.
    expect(window.geniro.updateSettings).toHaveBeenCalledWith({
      lastContextWindows: {},
    });
  });

  it('forgets the remembered model parameters when the model chip changes model', async () => {
    // Sharper than the window above: WHICH parameter ids exist at all is the
    // model's own answer, so a value kept across a model change names an axis
    // the new model never enumerated. The panel stops drawing that row, so
    // nothing on screen says the run is still being created with it.
    stubSettings({
      lastModels: { claude: 'sonnet' },
      lastModelParameters: { claude: { optimize_for: 'cost' } },
    });
    const { client } = makeClient();
    const container = await mount(client);

    await pickSetting(container, 'Model', 'opus');

    // The map WITHOUT claude's entry, for the same reason as the window test:
    // the stored value is what reaches the next run, so an unchanged
    // `{claude: {optimize_for: 'cost'}}` is exactly the defect.
    expect(window.geniro.updateSettings).toHaveBeenCalledWith({
      lastModelParameters: {},
    });
  });

  it('keeps the remembered window and parameters when the model ALREADY in force is picked again', async () => {
    // The checked row is still pressable, and the two forgets above fired on
    // it too — re-picking the current model wiped a window and a parameter
    // that still belonged to it.
    stubSettings({
      lastModels: { claude: 'sonnet' },
      lastContextWindows: { claude: '1m' },
      lastModelParameters: { claude: { optimize_for: 'cost' } },
    });
    const { client } = makeClient();
    const container = await mount(client);

    await pickSetting(container, 'Model', 'sonnet');

    const written = (
      window.geniro.updateSettings as ReturnType<typeof vi.fn>
    ).mock.calls.flatMap((call: unknown[]) => Object.keys(call[0] as object));
    expect(written).not.toContain('lastContextWindows');
    expect(written).not.toContain('lastModelParameters');
    expect(written).not.toContain('lastModels');
  });

