describe('Chats skill autocomplete', () => {
  const SKILLS = [
    {
      name: 'deploy',
      description: 'Ship the app',
      kind: 'skill' as const,
      source: 'project' as const,
    },
    {
      name: 'review',
      description: null,
      kind: 'command' as const,
      source: 'user' as const,
    },
  ];

  // jsdom has no `scrollIntoView`, which the popup calls on its highlighted
  // row. These tests passed only as part of the whole file, on a stub an
  // unrelated test earlier in it leaves on the prototype.
  beforeEach(() => {
    Element.prototype.scrollIntoView = vi.fn();
  });

  /** Type `value` into the (only) composer textarea through React's setter. */
  async function type(textarea: HTMLTextAreaElement, value: string) {
    await act(async () => {
      const setValue = Object.getOwnPropertyDescriptor(
        HTMLTextAreaElement.prototype,
        'value',
      )!.set!;
      setValue.call(textarea, value);
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
    });
  }

  async function keydown(textarea: HTMLTextAreaElement, key: string) {
    await act(async () => {
      textarea.dispatchEvent(
        new KeyboardEvent('keydown', { key, bubbles: true, cancelable: true }),
      );
    });
  }

  it('lists the open chat agent\'s skills on "/", filters, and inserts the pick on Enter', async () => {
    agentsApi.listAgentSkills.mockResolvedValue(SKILLS);
    const { client } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'My chat');
    // The list is fetched for the RUN's agent in the RUN's folder.
    expect(agentsApi.listAgentSkills).toHaveBeenCalledWith({
      agent: 'claude',
      cwd: '/proj',
    });

    const textarea = container.querySelector('textarea')!;
    await type(textarea, '/');
    const listbox = container.querySelector('[role="listbox"]')!;
    expect(listbox).not.toBeNull();
    expect(listbox.textContent).toContain('/deploy');
    expect(listbox.textContent).toContain('Ship the app');
    expect(listbox.textContent).toContain('/review');

    // Typing narrows the list…
    await type(textarea, '/rev');
    expect(
      container.querySelector('[role="listbox"]')!.textContent,
    ).not.toContain('/deploy');

    // …and Enter inserts the highlighted skill (never sends, never newlines).
    await keydown(textarea, 'Enter');
    expect(textarea.value).toBe('/review ');
    expect(container.querySelector('[role="listbox"]')).toBeNull();
    expect(api.sendChatMessage).not.toHaveBeenCalled();
  });

  it('closes on Escape for that query, stays closed for arguments, reopens on edit', async () => {
    agentsApi.listAgentSkills.mockResolvedValue(SKILLS);
    const { client } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'My chat');

    const textarea = container.querySelector('textarea')!;
    await type(textarea, '/de');
    expect(container.querySelector('[role="listbox"]')).not.toBeNull();
    await keydown(textarea, 'Escape');
    expect(container.querySelector('[role="listbox"]')).toBeNull();
    // Same dismissed query stays closed; editing the token reopens.
    await type(textarea, '/dep');
    expect(container.querySelector('[role="listbox"]')).not.toBeNull();
    // Arguments after the command never show the menu.
    await type(textarea, '/deploy now');
    expect(container.querySelector('[role="listbox"]')).toBeNull();
  });

  it("resolves a team target's skills through the selected trigger's member", async () => {
    agentsApi.listAgentSkills.mockResolvedValue([]);
    teamApi.listTeams.mockResolvedValue([
      {
        slug: 'review-team',
        name: 'Review team',
        description: null,
        memberCount: 2,
        agentCounts: [],
        updatedAt: 'now',
      },
    ]);
    teamApi.getTeam.mockResolvedValue({
      slug: 'review-team',
      team: {
        name: 'Review team',
        mode: 'lead',
        members: [
          {
            id: 'coder',
            name: 'coder',
            agent: 'cursor-agent',
            approval: 'auto',
          },
        ],
        triggers: [{ kind: 'first-message', member: 'coder' }],
        instructionBlocks: [],
      },
    });
    const { client } = makeClient();
    const container = await mount(client);

    await pickMenuRow(container, targetTrigger(container), 'Review team');

    // The skills fetched are the TRIGGER's member's, not the
    // composer's bare-agent default.
    expect(agentsApi.listAgentSkills).toHaveBeenCalledWith({
      agent: 'cursor-agent',
      cwd: '/proj',
    });
  });

  it("offers an OPEN team run the skills of the agents a follow-up lands in, under each one's profile", async () => {
    // REPORTED as a Dev Team thread with no `/` suggestions at all: the open
    // run asked about no agent, while its Manager ran the command fine.
    agentsApi.listAgentSkills.mockResolvedValue(SKILLS);
    teamApi.listTeamRuns.mockResolvedValue([
      {
        id: 'w1',
        status: 'completed',
        awaiting: null,
        holdingFor: 0,
        awaitingCalls: 0,
        shellsOpen: 0,
        subagentsOut: 0,
        title: 'Team run',
        agentKind: null,
        teamId: 'dev-team',
        cwd: '/proj',
        model: null,
        createdAt: 'later',
        updatedAt: 'later',
        lastMessage: null,
      },
    ]);
    teamApi.getTeamRunSnapshot.mockResolvedValue({
      team: {
        name: 'Dev team',
        mode: 'lead',
        members: [
          {
            id: 'manager',
            name: 'manager',
            agent: 'claude',
            approval: 'auto',
            configDir: '/profiles/lab',
          },
          { id: 'qa', name: 'qa', agent: 'cursor-agent', approval: 'auto' },
        ],
        triggers: [{ kind: 'first-message', member: 'manager' }],
        instructionBlocks: [],
      },
    });
    const { client } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'Team run');

    expect(agentsApi.listAgentSkills).toHaveBeenCalledWith({
      agent: 'claude',
      cwd: '/proj',
      configDir: '/profiles/lab',
    });
    // A callee is not where a follow-up goes, so its CLI is not asked.
    expect(agentsApi.listAgentSkills).not.toHaveBeenCalledWith(
      expect.objectContaining({ agent: 'cursor-agent' }),
    );
    const textarea = container.querySelector('textarea')!;
    await type(textarea, '/');
    expect(container.querySelector('[role="listbox"]')?.textContent).toContain(
      '/deploy',
    );
  });

  it('shows who leads an open relay run, follows a hand-off, and asks the lead’s CLI for skills', async () => {
    agentsApi.listAgentSkills.mockResolvedValue(SKILLS);
    teamApi.listTeamRuns.mockResolvedValue([
      {
        id: 'w1',
        status: 'completed',
        awaiting: null,
        holdingFor: 0,
        awaitingCalls: 0,
        shellsOpen: 0,
        subagentsOut: 0,
        title: 'Relay run',
        agentKind: null,
        teamId: 'relay-team',
        cwd: '/proj',
        model: null,
        createdAt: 'later',
        updatedAt: 'later',
        lastMessage: null,
        currentLead: 'qa',
      },
    ]);
    teamApi.getTeamRunSnapshot.mockResolvedValue({
      team: {
        name: 'Relay team',
        mode: 'relay',
        members: [
          { id: 'manager', name: 'Manager', agent: 'claude', approval: 'auto' },
          { id: 'qa', name: 'QA', agent: 'cursor-agent', approval: 'auto' },
        ],
        triggers: [{ kind: 'first-message', member: 'manager' }],
        instructionBlocks: [],
      },
    });
    const { client, emitRunStatus } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'Relay run');

    const chip = () =>
      container.querySelector('[data-slot="lead-chip"]')?.textContent ?? null;
    expect(chip()).toBe('Now leading:QA');
    expect(agentsApi.listAgentSkills).toHaveBeenCalledWith({
      agent: 'cursor-agent',
      cwd: '/proj',
    });

    await act(async () => {
      emitRunStatus({ runId: 'w1', status: null, currentLead: 'manager' });
    });
    expect(chip()).toBe('Now leading:Manager');
  });

  it('shows no lead chip on a one-lead team run', async () => {
    teamApi.listTeamRuns.mockResolvedValue([
      {
        id: 'w1',
        status: 'completed',
        awaiting: null,
        holdingFor: 0,
        awaitingCalls: 0,
        shellsOpen: 0,
        subagentsOut: 0,
        title: 'Lead run',
        agentKind: null,
        teamId: 'lead-team',
        cwd: '/proj',
        model: null,
        createdAt: 'later',
        updatedAt: 'later',
        lastMessage: null,
        currentLead: 'manager',
      },
    ]);
    teamApi.getTeamRunSnapshot.mockResolvedValue({
      team: {
        name: 'Lead team',
        mode: 'lead',
        members: [
          { id: 'manager', name: 'Manager', agent: 'claude', approval: 'auto' },
        ],
        triggers: [{ kind: 'first-message', member: 'manager' }],
        instructionBlocks: [],
      },
    });
    const { client } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'Lead run');

    expect(container.querySelector('[data-slot="agent-cards"]')).not.toBeNull();
    expect(container.querySelector('[data-slot="lead-chip"]')).toBeNull();
  });
});

