describe('Chats — a send and a paste that outlive a thread switch', () => {
  const run2: ChatRun = {
    ...run1,
    id: 'r2',
    title: 'Second chat',
    status: 'completed',
  };

  beforeEach(() => {
    // Both idle, so the composer SENDS rather than queueing — the send path
    // is what these cases are about.
    api.listChats.mockResolvedValue([{ ...run1, status: 'completed' }, run2]);
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  async function type(container: HTMLElement, text: string): Promise<void> {
    const textarea = container.querySelector('textarea')!;
    await act(async () => {
      Object.getOwnPropertyDescriptor(
        HTMLTextAreaElement.prototype,
        'value',
      )!.set!.call(textarea, text);
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
    });
  }

  async function clickButton(
    container: HTMLElement,
    label: string,
  ): Promise<void> {
    await act(async () => {
      container
        .querySelector(`button[aria-label="${label}"]`)
        ?.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    });
  }

  const staged = (container: HTMLElement): NodeListOf<Element> =>
    container.querySelectorAll('[data-slot="staged-attachment"]');

  const composerText = (container: HTMLElement): string =>
    container.querySelector('textarea')!.value;

  const pngFile = (name: string): File =>
    new File([new Uint8Array([0x89, 0x50, 0x4e, 0x47])], name, {
      type: 'image/png',
    });

  /** What the fake reader below hands back for every image. */
  const READ_BASE64 = 'iVBORw==';

  /**
   * Hold every image read at its decode until the case releases it — so a
   * paste is IN FLIGHT for exactly as long as the case needs — and finish the
   * rest of the read in a microtask, so a release lands deterministically
   * inside one `act`. jsdom's own `FileReader` completes on a timer of its
   * own, which is what an in-flight window cannot be built on.
   */
  function holdImageReads(): { release: () => Promise<void> } {
    const waiting: (() => void)[] = [];
    vi.stubGlobal(
      'createImageBitmap',
      () =>
        new Promise((resolve) => {
          // Inside the pixel ceiling, so nothing is re-encoded.
          waiting.push(() =>
            resolve({ width: 10, height: 10, close: () => {} }),
          );
        }),
    );
    vi.stubGlobal(
      'FileReader',
      class {
        result: string | null = null;
        onload: (() => void) | null = null;
        onerror: (() => void) | null = null;
        readAsDataURL(blob: Blob): void {
          this.result = `data:${blob.type};base64,${READ_BASE64}`;
          queueMicrotask(() => this.onload?.());
        }
      },
    );
    return {
      release: async () => {
        await act(async () => {
          for (const resolve of waiting.splice(0)) {
            resolve();
          }
          // One macrotask drains every microtask the read chains through.
          await new Promise((resolve) => setTimeout(resolve, 0));
        });
      },
    };
  }

  async function paste(container: HTMLElement, files: File[]): Promise<void> {
    const textarea = container.querySelector('textarea')!;
    const event = new Event('paste', { bubbles: true, cancelable: true });
    Object.defineProperty(event, 'clipboardData', { value: { files } });
    await act(async () => {
      textarea.dispatchEvent(event);
    });
  }

  it('holds Send while a pasted image is still being READ — the message never leaves without it', async () => {
    // Enter straight after a paste sent the text ALONE: the read is async, and
    // the send took whatever had landed, which was nothing yet.
    const reads = holdImageReads();
    api.sendChatMessage.mockResolvedValue(
      msg(10, 'user', 'what is wrong here'),
    );
    const { client } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'My chat');

    await type(container, 'what is wrong here');
    await paste(container, [pngFile('shot.png')]);

    const send = composerButton(container, 'Send')!;
    expect(send.getAttribute('aria-disabled')).toBe('true');
    expect(send.title).toContain('Reading the pasted image');
    // Neither the press nor Enter lets the text go without its picture.
    await clickButton(container, 'Send');
    await act(async () => {
      container
        .querySelector('textarea')!
        .dispatchEvent(
          new KeyboardEvent('keydown', { key: 'Enter', bubbles: true }),
        );
    });
    expect(api.sendChatMessage).not.toHaveBeenCalled();

    await reads.release();
    expect(staged(container)).toHaveLength(1);
    expect(
      composerButton(container, 'Send')!.getAttribute('aria-disabled'),
    ).toBe('false');
    await clickButton(container, 'Send');
    expect(api.sendChatMessage).toHaveBeenCalledWith({
      runId: 'r1',
      sendMessageDto: {
        clientMessageId: expect.any(String),
        text: 'what is wrong here',
        images: [{ mediaType: 'image/png', data: READ_BASE64 }],
      },
    });
  });

  it('holds the NEW-CHAT composer’s Send the same way while its paste is read', async () => {
    // The landing card is the other door a first message leaves by, with the
    // same async read in front of it.
    const reads = holdImageReads();
    api.createChat.mockResolvedValue({ ...run1, id: 'r-new' });
    api.sendChatMessage.mockResolvedValue(msg(0, 'user', 'first message'));
    const { client } = makeClient();
    const container = await mount(client);

    await type(container, 'first message');
    await paste(container, [pngFile('shot.png')]);
    const send = composerButton(container, 'Send')!;
    expect(send.getAttribute('aria-disabled')).toBe('true');
    expect(send.title).toContain('Reading the pasted image');
    await clickButton(container, 'Send');
    expect(api.createChat).not.toHaveBeenCalled();

    await reads.release();
    await clickButton(container, 'Send');
    expect(api.sendChatMessage).toHaveBeenCalledWith({
      runId: 'r-new',
      sendMessageDto: {
        clientMessageId: expect.any(String),
        text: 'first message',
        images: [{ mediaType: 'image/png', data: READ_BASE64 }],
      },
    });
  });

  it('lands an image still being read when the thread is switched in ITS thread, never the one on screen', async () => {
    // One stage serves every thread's draft in turn, and the read outlived the
    // switch: the screenshot turned up staged in the other conversation — the
    // one it could then be sent from.
    const reads = holdImageReads();
    const { client } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'My chat');

    await paste(container, [pngFile('shot.png')]);
    await clickRun(container, 'Second chat');
    // This thread's Send is not held for another thread's read.
    await type(container, 'hello');
    expect(
      composerButton(container, 'Send')!.getAttribute('aria-disabled'),
    ).toBe('false');

    await reads.release();
    expect(staged(container)).toHaveLength(0);

    await clickRun(container, 'My chat');
    expect(staged(container)).toHaveLength(1);
  });

  it('parks no more images in an off-screen draft than one message can carry', async () => {
    // The cap the live stage enforces, where nothing on screen can say so: the
    // daemon refuses a message over it whole, so a ninth image parked here
    // would cost the other eight their send.
    const reads = holdImageReads();
    const { client } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'My chat');

    await paste(
      container,
      Array.from({ length: 8 }, (_, index) => pngFile(`shot-${index}.png`)),
    );
    await reads.release();
    expect(staged(container)).toHaveLength(8);

    await paste(container, [pngFile('one-too-many.png')]);
    await clickRun(container, 'Second chat');
    await reads.release();
    await clickRun(container, 'My chat');

    expect(staged(container)).toHaveLength(8);
  });

  it('keeps an image pasted WHILE a follow-up is sending — the send gives up only what it sent', async () => {
    // Clearing the composer AFTER the send lands would take an image pasted
    // during the POST with it.
    const reads = holdImageReads();
    let land!: (item: ChatItem) => void;
    api.sendChatMessage.mockImplementationOnce(
      () =>
        new Promise<ChatItem>((resolve) => {
          land = resolve;
        }),
    );
    const { client } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'My chat');

    await type(container, 'first thought');
    await clickButton(container, 'Send');
    expect(api.sendChatMessage).toHaveBeenCalledTimes(1);

    await paste(container, [pngFile('next.png')]);
    await reads.release();
    expect(staged(container)).toHaveLength(1);

    await act(async () => {
      land(msg(10, 'user', 'first thought'));
    });
    expect(staged(container)).toHaveLength(1);
  });

  it('puts a follow-up that FAILS after a thread switch back in its own thread — nothing of it in the other', async () => {
    // Images left staged through the send would be parked by the switch as
    // that thread's draft, and the failure would then write the text and the
    // error into the thread switched TO.
    const reads = holdImageReads();
    let fail!: (err: unknown) => void;
    api.sendChatMessage.mockImplementationOnce(
      () =>
        new Promise<ChatItem>((_resolve, reject) => {
          fail = reject;
        }),
    );
    const { client } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'My chat');

    await paste(container, [pngFile('shot.png')]);
    await reads.release();
    await type(container, 'look at this');
    await clickButton(container, 'Send');
    expect(api.sendChatMessage).toHaveBeenCalledTimes(1);
    // Emptied at once — the images with the text.
    expect(composerText(container)).toBe('');
    expect(staged(container)).toHaveLength(0);

    await clickRun(container, 'Second chat');
    await act(async () => {
      fail(new Error('daemon unreachable'));
    });

    expect(composerText(container)).toBe('');
    expect(staged(container)).toHaveLength(0);
    expect(container.textContent).not.toContain('daemon unreachable');

    // …and every part of it back in the thread it was written in.
    await clickRun(container, 'My chat');
    expect(composerText(container)).toBe('look at this');
    expect(staged(container)).toHaveLength(1);
  });

  it('puts a follow-up that fails in the SAME thread back on screen, image included, with the error', async () => {
    // The composer is emptied before the send now, so the images come back by
    // being PUT back — before, they were simply never taken off.
    const reads = holdImageReads();
    api.sendChatMessage.mockRejectedValueOnce(new Error('daemon unreachable'));
    const { client } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'My chat');

    await paste(container, [pngFile('shot.png')]);
    await reads.release();
    await type(container, 'look at this');
    await clickButton(container, 'Send');

    expect(container.textContent).toContain('daemon unreachable');
    expect(composerText(container)).toBe('look at this');
    expect(staged(container)).toHaveLength(1);
  });

  it('neither brings a SENT image back to its thread nor wipes the other thread’s, across a switch', async () => {
    const reads = holdImageReads();
    let land!: (item: ChatItem) => void;
    api.sendChatMessage.mockImplementationOnce(
      () =>
        new Promise<ChatItem>((resolve) => {
          land = resolve;
        }),
    );
    const { client } = makeClient();
    const container = await mount(client);
    await clickRun(container, 'My chat');

    await paste(container, [pngFile('sent.png')]);
    await reads.release();
    await type(container, 'look at this');
    await clickButton(container, 'Send');

    await clickRun(container, 'Second chat');
    await paste(container, [pngFile('mine.png')]);
    await reads.release();
    expect(staged(container)).toHaveLength(1);

    await act(async () => {
      land(msg(10, 'user', 'look at this'));
    });
    // The other thread's own image survives the send landing…
    expect(staged(container)).toHaveLength(1);

    // …and the one that went out is not waiting to go out again.
    await clickRun(container, 'My chat');
    expect(staged(container)).toHaveLength(0);
    expect(composerText(container)).toBe('');
  });
});

describe('Chats — searching every chat', () => {
  const run2: ChatRun = { ...run1, id: 'r2', title: 'Billing chat' };

  function hitIn(runId: string, seq: number, archived = false) {
    return {
      runId,
      itemId: `${runId}-${seq}`,
      memberId: null,
      seq,
      kind: 'message' as const,
      role: 'assistant',
      snippet: 'sizing the bloom filter',
      createdAt: '2026-01-01T00:00:00.000Z',
      title: 'Billing chat',
      cwd: '/proj',
      archived,
      score: 1,
    };
  }

  async function pressShortcut(
    modifier: 'meta' | 'ctrl' = 'meta',
  ): Promise<void> {
    await act(async () => {
      window.dispatchEvent(
        new KeyboardEvent('keydown', {
          code: 'KeyF',
          key: 'F',
          metaKey: modifier === 'meta',
          ctrlKey: modifier === 'ctrl',
          shiftKey: true,
        }),
      );
    });
  }

  /** Open the dialog with the shortcut, search, and press the first hit. */
  async function pickHit(container: HTMLElement): Promise<void> {
    await pressShortcut();
    const field = container.querySelector<HTMLInputElement>(
      'input[aria-label="Search all chats"]',
    )!;
    await act(async () => {
      typeInto(field, 'bloom');
    });
    await act(async () => {
      await vi.advanceTimersByTimeAsync(400);
    });
    const hit = [
      ...container.querySelectorAll<HTMLButtonElement>('button'),
    ].find((button) =>
      button.textContent?.includes('sizing the bloom filter'),
    )!;
    await act(async () => {
      hit.click();
    });
  }

  beforeEach(() => {
    vi.useFakeTimers({ shouldAdvanceTime: true });
    api.listChats.mockResolvedValue([run1, run2]);
  });
  afterEach(() => {
    vi.useRealTimers();
  });

  it('opens on Cmd+Shift+F only while this screen is the one shown', async () => {
    const { client } = makeClient();
    const hidden = await mount(client, undefined, { active: false });
    await pressShortcut();
    expect(
      hidden.querySelector('input[aria-label="Search all chats"]'),
    ).toBeNull();

    const shown = await mount(makeClient().client);
    await pressShortcut();
    expect(
      shown.querySelector('input[aria-label="Search all chats"]'),
    ).not.toBeNull();
  });

  it('opens on Ctrl+Shift+F as well, for a keyboard without Cmd', async () => {
    const container = await mount(makeClient().client);
    await pressShortcut('ctrl');
    expect(
      container.querySelector('input[aria-label="Search all chats"]'),
    ).not.toBeNull();
  });

  it('opens the hit’s chat and fetches the window around it once it loads', async () => {
    api.listRunItems.mockResolvedValue([msg(900, 'user', 'newest')]);
    api.searchAllChats.mockResolvedValue({
      hits: [hitIn('r2', 12)],
      partialReason: null,
    });
    const container = await mount(makeClient().client);
    await clickRun(container, 'My chat');

    await pickHit(container);
    await act(async () => {
      await vi.advanceTimersByTimeAsync(50);
    });

    expect(api.listRunItems).toHaveBeenCalledWith(
      expect.objectContaining({ runId: 'r2', beforeSeq: 62 }),
    );
  });

  it('waits for the hit’s chat to load before jumping, so its first page cannot replace the window', async () => {
    let releaseR2: (() => void) | null = null;
    api.listRunItems.mockImplementation(
      (args: { runId: string; beforeSeq?: number }) =>
        args.runId === 'r2' && args.beforeSeq === undefined
          ? new Promise((resolve) => {
              releaseR2 = () => resolve([msg(900, 'user', 'newest')]);
            })
          : Promise.resolve([msg(900, 'user', 'newest')]),
    );
    api.searchAllChats.mockResolvedValue({
      hits: [hitIn('r2', 12)],
      partialReason: null,
    });
    const container = await mount(makeClient().client);
    await clickRun(container, 'My chat');
    await pickHit(container);
    await act(async () => {
      await vi.advanceTimersByTimeAsync(50);
    });
    expect(api.listRunItems).not.toHaveBeenCalledWith(
      expect.objectContaining({ runId: 'r2', beforeSeq: 62 }),
    );

    await act(async () => {
      releaseR2?.();
    });
    await act(async () => {
      await vi.advanceTimersByTimeAsync(50);
    });
    expect(api.listRunItems).toHaveBeenCalledWith(
      expect.objectContaining({ runId: 'r2', beforeSeq: 62 }),
    );
  });

  it('shows every chat when a live hit is picked while only the archive is listed', async () => {
    api.searchAllChats.mockResolvedValue({
      hits: [hitIn('r2', 12, false)],
      partialReason: null,
    });
    const container = await mount(makeClient().client);
    await pickScope(container, 'Archived only');
    api.listChats.mockClear();
    await pickHit(container);
    expect(api.listChats).toHaveBeenCalledWith({
      scope: 'all',
      limit: RUN_LIST_PAGE + 1,
    });
  });

  it('shows the archive too when the hit is in an archived chat', async () => {
    api.searchAllChats.mockResolvedValue({
      hits: [hitIn('r2', 12, true)],
      partialReason: null,
    });
    const container = await mount(makeClient().client);
    await pickHit(container);
    expect(api.listChats).toHaveBeenCalledWith({
      scope: 'all',
      limit: RUN_LIST_PAGE + 1,
    });
  });

  it('drops the jump when another chat is opened before the hit’s chat loads', async () => {
    let releaseR2: (() => void) | null = null;
    api.listRunItems.mockImplementation((args: { runId: string }) =>
      args.runId === 'r2' && releaseR2 === null
        ? new Promise((resolve) => {
            releaseR2 = () => resolve([msg(900, 'user', 'newest')]);
          })
        : Promise.resolve([msg(900, 'user', 'newest')]),
    );
    api.searchAllChats.mockResolvedValue({
      hits: [hitIn('r2', 12)],
      partialReason: null,
    });
    const container = await mount(makeClient().client);
    await clickRun(container, 'My chat');
    await pickHit(container);

    await clickRun(container, 'My chat');
    await act(async () => {
      releaseR2?.();
    });
    api.listRunItems.mockClear();
    await clickRun(container, 'Billing chat');
    await act(async () => {
      await vi.advanceTimersByTimeAsync(50);
    });

    expect(api.listRunItems).not.toHaveBeenCalledWith(
      expect.objectContaining({ beforeSeq: 62 }),
    );
  });
});

/**
 * The team builder's chat dock and the analysis popups draw their one
 * conversation with this screen itself (`hosted`), so it reads, queues and
 * shows exactly as a thread does. What the surface is told back is pinned here.
 */
describe('Chats — one hosted conversation', () => {
  const HOSTED: ChatRun = {
    ...run1,
    id: 'h1',
    title: 'Change Dev Team',
    status: 'completed',
  };
  const hostedRow = (item: ChatItem): ChatItem => ({
    ...item,
    id: `h-${item.id}`,
    runId: 'h1',
  });

  function hostedThread(overrides: Partial<HostedThread> = {}): HostedThread & {
    open: ReturnType<typeof vi.fn>;
  } {
    return {
      open: vi.fn(async () => HOSTED),
      queueScope: 'team-chat:dev-team',
      emptyText: 'Ask for a team change.',
      composerLabel: 'Ask for a team change',
      composerPlaceholder: 'Describe the change…',
      ...overrides,
    } as HostedThread & { open: ReturnType<typeof vi.fn> };
  }

  async function typeAndSend(
    container: HTMLElement,
    text: string,
  ): Promise<void> {
    const textarea = container.querySelector('textarea')!;
    await act(async () => {
      Object.getOwnPropertyDescriptor(
        HTMLTextAreaElement.prototype,
        'value',
      )!.set!.call(textarea, text);
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
    });
    await act(async () => {
      textarea.dispatchEvent(
        new KeyboardEvent('keydown', { key: 'Enter', bubbles: true }),
      );
    });
  }

  it('draws the one conversation the surface opens, with no list and no new-chat composer', async () => {
    const { client } = makeClient();
    const hosted = hostedThread({
      headerActions: () => <button type="button">Hide the dock</button>,
    });

    const container = await mount(client, undefined, { hosted });

    expect(hosted.open).toHaveBeenCalledTimes(1);
    expect(api.listChats).not.toHaveBeenCalled();
    expect(container.querySelector('[data-slot="chat-list"]')).toBeNull();
    expect(
      container.querySelector('[data-slot="chat-header"]')?.textContent,
    ).toContain('Change Dev Team');
    expect(
      container.querySelector('[data-slot="chat-header-actions"]')?.textContent,
    ).toBe('Hide the dock');
    expect(
      container.querySelector('[data-slot="composer-shelf"]'),
    ).not.toBeNull();
  });

  it('tells the surface a chip changed the conversation’s settings, and not a refused one', async () => {
    const { client } = makeClient();
    const onRunSettingsChanged = vi.fn();
    const updated = { ...HOSTED, model: 'opus' };
    api.updateChatSettings.mockResolvedValueOnce(updated);
    const container = await mount(client, undefined, {
      hosted: hostedThread({ onRunSettingsChanged }),
    });

    await pickSetting(container, 'Model', 'opus');

    expect(onRunSettingsChanged).toHaveBeenCalledTimes(1);
    expect(onRunSettingsChanged).toHaveBeenCalledWith(updated);

    api.updateChatSettings.mockRejectedValueOnce(new Error('refused'));
    await pickSetting(container, 'Model', 'default model');

    expect(api.updateChatSettings).toHaveBeenCalledTimes(2);
    expect(onRunSettingsChanged).toHaveBeenCalledTimes(1);
  });

  it('says what an empty conversation is for, in the composer the surface names', async () => {
    const { client } = makeClient();

    const container = await mount(client, undefined, {
      hosted: hostedThread({ initialDraft: 'Add a QA member' }),
    });

    expect(
      container.querySelector('[data-slot="hosted-thread-empty"]')?.textContent,
    ).toBe('Ask for a team change.');
    const textarea = container.querySelector<HTMLTextAreaElement>(
      'textarea[aria-label="Ask for a team change"]',
    );
    expect(textarea?.placeholder).toBe('Describe the change…');
    expect(textarea?.value).toBe('Add a QA member');
  });

  it('runs the surface’s step before a message goes out', async () => {
    api.sendChatMessage.mockResolvedValue(hostedRow(msg(0, 'user', 'go')));
    const onBeforeSend = vi.fn(async () => true);
    const { client } = makeClient();
    const container = await mount(client, undefined, {
      hosted: hostedThread({ onBeforeSend }),
    });

    await typeAndSend(container, 'go');

    expect(onBeforeSend).toHaveBeenCalledTimes(1);
    expect(api.sendChatMessage).toHaveBeenCalledTimes(1);
    expect(onBeforeSend.mock.invocationCallOrder[0]!).toBeLessThan(
      api.sendChatMessage.mock.invocationCallOrder[0]!,
    );
  });

  it('reports each turn: working while it runs, and its end once per turn', async () => {
    api.sendChatMessage.mockResolvedValue(hostedRow(msg(0, 'user', 'go')));
    const onWorkingChange = vi.fn();
    const onTurnSettled = vi.fn();
    const { client, emitItem } = makeClient();
    const container = await mount(client, undefined, {
      hosted: hostedThread({ onWorkingChange, onTurnSettled }),
    });

    await typeAndSend(container, 'go');
    expect(onWorkingChange).toHaveBeenLastCalledWith(true);
    await act(async () => {
      emitItem(hostedRow(terminal(1)));
    });
    expect(onWorkingChange).toHaveBeenLastCalledWith(false);
    expect(onTurnSettled).toHaveBeenCalledTimes(1);

    api.sendChatMessage.mockResolvedValue(hostedRow(msg(2, 'user', 'again')));
    await typeAndSend(container, 'again');
    await act(async () => {
      emitItem(hostedRow(terminal(3)));
    });
    expect(onTurnSettled).toHaveBeenCalledTimes(2);
  });

  it('tells the surface what the agent is waiting on', async () => {
    const onAwaitingChange = vi.fn();
    const { client, emitRunStatus } = makeClient();
    await mount(client, undefined, {
      hosted: hostedThread({ onAwaitingChange }),
    });

    await act(async () => {
      emitRunStatus({ runId: 'h1', status: null, awaiting: 'question' });
    });
    expect(onAwaitingChange).toHaveBeenLastCalledWith('question');

    await act(async () => {
      emitRunStatus({ runId: 'h1', status: null, awaiting: null });
    });
    expect(onAwaitingChange).toHaveBeenLastCalledWith(null);
  });

  it('queues a message typed while the agent works, as a thread does', async () => {
    const { client } = makeClient();
    const container = await mount(client, undefined, {
      hosted: hostedThread({
        open: vi.fn(async () => ({ ...HOSTED, status: 'running' as const })),
      }),
    });

    await typeAndSend(container, 'and the reviewer too');

    expect(api.sendChatMessage).not.toHaveBeenCalled();
    expect(
      container.querySelector('[data-slot="queued-message"]')?.textContent,
    ).toContain('and the reviewer too');
  });

  it('starts over from the surface’s control: throws the conversation away and opens the next', async () => {
    const discard = vi.fn(async () => undefined);
    const open = vi
      .fn()
      .mockResolvedValueOnce(HOSTED)
      .mockResolvedValueOnce({ ...HOSTED, id: 'h2', title: 'Fresh chat' });
    const { client } = makeClient();
    const container = await mount(client, undefined, {
      hosted: hostedThread({
        open,
        discard,
        headerActions: ({ discard: startOver }) => (
          <button type="button" onClick={() => startOver?.()}>
            Start over
          </button>
        ),
      }),
    });

    const button = [...container.querySelectorAll('button')].find(
      (candidate) => candidate.textContent === 'Start over',
    );
    await act(async () => {
      button!.click();
    });

    expect(discard).toHaveBeenCalledTimes(1);
    expect(open).toHaveBeenCalledTimes(2);
    expect(
      container.querySelector('[data-slot="chat-header"]')?.textContent,
    ).toContain('Fresh chat');
  });

  it('does none of the whole app’s work: no notifications, no archive sweep, no Analyze', async () => {
    (
      window as unknown as { geniro: { getSettings: ReturnType<typeof vi.fn> } }
    ).geniro.getSettings.mockResolvedValue({
      onboardingComplete: true,
      projectFolder: '/proj',
      recentFolders: [],
      lastChatTarget: null,
      cliPaths: {},
      checkForUpdates: true,
      archiveRetentionDays: 30,
    });
    const hasFocus = vi.spyOn(document, 'hasFocus').mockReturnValue(false);
    const { client, emitItem } = makeClient();
    const container = await mount(client, undefined, {
      hosted: hostedThread({
        open: vi.fn(async () => ({ ...HOSTED, status: 'running' as const })),
      }),
    });
    notify.mockClear();

    await act(async () => {
      emitItem(hostedRow(terminal(1)));
    });

    expect(notify).not.toHaveBeenCalled();
    hasFocus.mockRestore();
    expect(window.geniro.onNotificationActivated).not.toHaveBeenCalled();
    expect(api.sweepArchivedChats).not.toHaveBeenCalled();
    expect(
      container.querySelector('button[aria-label="Analyze thread"]'),
    ).toBeNull();
  });

  // Closing the dock or the popup, or a reload, must not lose what was queued:
  // the queue is stored under the surface's own key and goes out once the
  // surface is back and its agent is free.
  it('keeps its queue under its own key, and sends it once the surface is back', async () => {
    localStorage.removeItem('geniro.queuedMessages:team-chat:dev-team');
    const first = makeClient();
    const working = await mount(first.client, undefined, {
      hosted: hostedThread({
        open: vi.fn(async () => ({ ...HOSTED, status: 'running' as const })),
      }),
    });
    await typeAndSend(working, 'and the reviewer too');

    const stored = JSON.parse(
      localStorage.getItem('geniro.queuedMessages:team-chat:dev-team') ??
        'null',
    ) as { queues: Record<string, { text: string }[]> } | null;
    expect(stored?.queues.h1?.[0]?.text).toBe('and the reviewer too');
    expect(localStorage.getItem('geniro.queuedMessages')).toBeNull();

    act(() => {
      roots.pop()?.unmount();
    });
    api.sendChatMessage.mockResolvedValue(
      hostedRow(msg(4, 'user', 'and the reviewer too')),
    );
    const second = makeClient();
    await mount(second.client, undefined, { hosted: hostedThread() });
    await act(async () => {
      await Promise.resolve();
    });

    expect(api.sendChatMessage).toHaveBeenCalledWith(
      expect.objectContaining({
        runId: 'h1',
        sendMessageDto: expect.objectContaining({
          text: 'and the reviewer too',
        }),
      }),
    );
    localStorage.removeItem('geniro.queuedMessages:team-chat:dev-team');
  });

  // The builder re-reads the team when a turn ends, and its next send waits on
  // that re-read; the message queued behind the turn goes out in the same tick.
  it('reports a turn’s end before the message queued behind it goes out', async () => {
    api.sendChatMessage.mockResolvedValue(hostedRow(msg(2, 'user', 'next')));
    const onTurnSettled = vi.fn();
    const { client, emitItem } = makeClient();
    const container = await mount(client, undefined, {
      hosted: hostedThread({
        open: vi.fn(async () => ({ ...HOSTED, status: 'running' as const })),
        onTurnSettled,
      }),
    });
    await typeAndSend(container, 'next');
    expect(api.sendChatMessage).not.toHaveBeenCalled();

    await act(async () => {
      emitItem(hostedRow(terminal(1)));
    });

    expect(onTurnSettled).toHaveBeenCalledTimes(1);
    expect(api.sendChatMessage).toHaveBeenCalledTimes(1);
    expect(onTurnSettled.mock.invocationCallOrder[0]!).toBeLessThan(
      api.sendChatMessage.mock.invocationCallOrder[0]!,
    );
  });

  it('runs the surface’s step before an agent’s button press reaches the daemon', async () => {
    api.readRunState.mockResolvedValue({
      ...emptyRunState(),
      actions: [
        {
          seq: 5,
          actionId: 'go-on',
          memberId: null,
          conversationId: null,
          label: 'Go on',
          once: true,
          spec: { kind: 'message', text: 'go on' },
          publisher: {
            nodeId: null,
            conversationId: null,
            callId: null,
            agentLabel: null,
          },
          pending: false,
        },
      ],
    });
    api.pressChatAction.mockResolvedValue({
      outcome: {
        actionSeq: 5,
        actionId: 'go-on',
        memberId: null,
        conversationId: null,
        state: 'succeeded',
      },
    });
    const onBeforeSend = vi.fn(async () => true);
    const onWorkingChange = vi.fn();
    const { client } = makeClient();
    const container = await mount(client, undefined, {
      hosted: hostedThread({ onBeforeSend, onWorkingChange }),
    });

    const chip = container.querySelector<HTMLButtonElement>(
      '[data-slot="chat-actions"] [data-slot="action-chip"]',
    );
    await act(async () => chip!.click());

    expect(onBeforeSend).toHaveBeenCalledTimes(1);
    expect(api.pressChatAction).toHaveBeenCalledTimes(1);
    expect(onBeforeSend.mock.invocationCallOrder[0]!).toBeLessThan(
      api.pressChatAction.mock.invocationCallOrder[0]!,
    );
    expect(onWorkingChange).toHaveBeenLastCalledWith(true);
  });

  const RECOMMENDATIONS_CARD = {
    id: 'h-card',
    runId: 'h1',
    memberId: null,
    seq: 7,
    kind: 'recommendations',
    role: null,
    payload: {
      sourceRunId: 'source',
      sourceKind: 'chat',
      summary: 'the reply named no pull request',
      timing: null,
      items: [
        {
          id: 'R-1',
          target: 'repo',
          territory: 'process',
          kind: 'ADD',
          location: 'AGENTS.md',
          title: 'Report every opened PR by URL',
          change: 'WHEN a PR is opened → name its URL',
          evidence: [{ seq: 2, quote: 'Done.' }],
          rootCause: 'termination',
          impact: {
            minutesSaved: 1,
            basis: 'one follow-up turn',
            confidence: 2,
          },
          risk: { level: 'low', note: 'longer replies' },
        },
      ],
    },
    createdAt: '2026-10-15T00:00:07.000Z',
  } as unknown as ChatItem;

  // An Apply starts a turn, so the surface's step runs before it as before a send.
  it('applies the card’s selection for its run, after the surface’s step', async () => {
    api.listRunItems.mockResolvedValue([RECOMMENDATIONS_CARD]);
    api.applyRecommendations.mockReset().mockResolvedValue(undefined);
    const onBeforeSend = vi.fn(async () => true);
    const onWorkingChange = vi.fn();
    const { client } = makeClient();
    const container = await mount(client, undefined, {
      hosted: hostedThread({ onBeforeSend, onWorkingChange }),
    });
    const buttons = (): HTMLButtonElement[] => [
      ...container.querySelectorAll<HTMLButtonElement>('button'),
    ];

    await act(async () => {
      buttons()
        .find((b) => b.textContent?.includes('R-1'))!
        .click();
    });
    await act(async () => {
      buttons()
        .find((b) => b.textContent?.includes('Apply selected'))!
        .click();
    });

    expect(api.applyRecommendations).toHaveBeenCalledWith({
      runId: 'h1',
      applyRecommendationsDto: expect.objectContaining({
        cardSeq: 7,
        ids: ['R-1'],
      }),
    });
    expect(onBeforeSend.mock.invocationCallOrder[0]!).toBeLessThan(
      api.applyRecommendations.mock.invocationCallOrder[0]!,
    );
    expect(onWorkingChange).toHaveBeenLastCalledWith(true);
  });

  describe('an analysis whose card’s worktree was collected', () => {
    const missingFolder = (route: string): Error =>
      new Error(
        `daemon POST /v1/chats/a1/${route} failed (400): {"code":"INVALID_CWD","message":"cwd does not exist: /userData/worktrees/t1"}`,
      );
    const analysis: ChatRun = {
      ...HOSTED,
      id: 'a1',
      title: 'Analysis: GEN-1',
      taskId: null,
      cwd: '/userData/worktrees/t1',
      analysisSourceRunId: 'source',
    };

    const analysisRow = (item: ChatItem): ChatItem => ({
      ...item,
      id: `a-${item.id}`,
      runId: 'a1',
    });

    function stubCardWorktree(): ReturnType<typeof vi.fn> {
      tasksApi.readTask.mockReset().mockResolvedValue({
        id: 't1',
        projectId: 'p1',
        folder: '/repo',
        worktreePath: '/userData/worktrees/t1',
      });
      const prepareTaskWorktree = vi.fn().mockResolvedValue({
        ok: true,
        path: '/userData/worktrees/t1',
        branch: 'geniro/task-t1',
        reused: false,
        error: null,
      });
      window.geniro.prepareTaskWorktree = prepareTaskWorktree;
      return prepareTaskWorktree;
    }

    it('puts the worktree back and applies the selection after all', async () => {
      api.listRunItems.mockResolvedValue([
        { ...RECOMMENDATIONS_CARD, id: 'a-card', runId: 'a1' },
      ]);
      api.applyRecommendations
        .mockReset()
        .mockRejectedValueOnce(missingFolder('recommendations/apply'))
        .mockResolvedValueOnce(undefined);
      const prepareTaskWorktree = stubCardWorktree();
      const { client } = makeClient();
      const container = await mount(client, undefined, {
        hosted: hostedThread({ open: vi.fn(async () => analysis) }),
      });
      const buttons = (): HTMLButtonElement[] => [
        ...container.querySelectorAll<HTMLButtonElement>('button'),
      ];

      await act(async () => {
        buttons()
          .find((b) => b.textContent?.includes('R-1'))!
          .click();
      });
      await act(async () => {
        buttons()
          .find((b) => b.textContent?.includes('Apply selected'))!
          .click();
      });

      expect(tasksApi.readTask).toHaveBeenCalledWith({ taskId: 't1' });
      expect(prepareTaskWorktree).toHaveBeenCalledWith({
        taskId: 't1',
        folder: '/repo',
      });
      expect(api.applyRecommendations).toHaveBeenCalledTimes(2);
      const [first, second] = api.applyRecommendations.mock.calls;
      expect(second![0]).toEqual(first![0]);
      expect(container.textContent).not.toContain('cwd does not exist');
    });

    it('puts the worktree back and sends a typed message after all', async () => {
      api.listRunItems.mockResolvedValue([analysisRow(msg(0, 'user', 'go'))]);
      api.sendChatMessage
        .mockReset()
        .mockRejectedValueOnce(missingFolder('messages'))
        .mockResolvedValueOnce(analysisRow(msg(10, 'user', 'and this?')));
      const prepareTaskWorktree = stubCardWorktree();
      const { client } = makeClient();
      const container = await mount(client, undefined, {
        hosted: hostedThread({ open: vi.fn(async () => analysis) }),
      });

      await typeAndSend(container, 'and this?');

      expect(prepareTaskWorktree).toHaveBeenCalledWith({
        taskId: 't1',
        folder: '/repo',
      });
      expect(api.sendChatMessage).toHaveBeenCalledTimes(2);
      expect(container.textContent).not.toContain('cwd does not exist');
    });
  });

  it('runs the surface’s step before a Retry reopens the conversation', async () => {
    api.listRunItems.mockResolvedValue([
      hostedRow(msg(0, 'user', 'go')),
      {
        ...hostedRow(msg(1, 'assistant', '')),
        kind: 'error',
        role: null,
        payload: { message: 'the CLI exited' },
      },
    ]);
    api.retryChat.mockReset().mockResolvedValue(undefined);
    const onBeforeSend = vi.fn(async () => true);
    const onWorkingChange = vi.fn();
    const { client } = makeClient();
    const container = await mount(client, undefined, {
      hosted: hostedThread({
        open: vi.fn(async () => ({ ...HOSTED, status: 'failed' as const })),
        onBeforeSend,
        onWorkingChange,
      }),
    });

    const retry = [...container.querySelectorAll('button')].find(
      (b) => b.textContent?.trim() === 'Retry',
    );
    await act(async () => {
      retry!.click();
    });

    expect(api.retryChat).toHaveBeenCalledWith({ runId: 'h1' });
    expect(onBeforeSend.mock.invocationCallOrder[0]!).toBeLessThan(
      api.retryChat.mock.invocationCallOrder[0]!,
    );
    expect(onWorkingChange).toHaveBeenLastCalledWith(true);
  });

  it('says why the conversation could not be opened, and asks again on Try again', async () => {
    const open = vi
      .fn()
      .mockRejectedValueOnce(new Error('This thread has no analysis yet.'))
      .mockResolvedValueOnce(HOSTED);
    const { client } = makeClient();
    const container = await mount(client, undefined, {
      hosted: hostedThread({ open }),
    });

    expect(container.textContent).toContain('This thread has no analysis yet.');
    const retry = [...container.querySelectorAll('button')].find(
      (candidate) => candidate.textContent === 'Try again',
    );
    await act(async () => {
      retry!.click();
    });

    expect(open).toHaveBeenCalledTimes(2);
    expect(container.querySelector('[data-slot="chat-header"]')).not.toBeNull();
  });
});
